head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


sdate = "";
statusStr = "공시 제출 가능 시간은 평일 18:00 까지 입니다.";

// 현재시간
/**
 * @method
 * @name fn_GetCurrentTime
 * @description desc
 * @param {string} _frm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_GetCurrentTime = function(_frm) {
    try {
        var frm = _frm;
        frm.method.setValue("getCurrentTime");
        frm.action = "mainIntro.do";
        eval("var result = " + responseTextXMLHTTP(frm, "post"));
        if (scwin.sdate == "") {
            scwin.sdate = Date.parse(result.currentTime, "yyyy-MM-dd HH:mm:ss");
            if (result.businessClosing == 'Y') {
                scwin.statusStr = "";
            } else if (result.businessClosing == 'N') {
                scwin.statusStr = "";
            }
        }
        scwin.fn_SetCurrentTime();
    } catch (e) {
        var tmp = 1;
    }
};



/** 현재시간 */
/**
 * @method
 * @name fn_SetCurrentTime
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_SetCurrentTime = function() {
    window.setTimeout("fn_SetCurrentTime()", 1000);
    sdate.addMilliseconds(1000);
    var currentTimeStr = sdate.toString("yyyy-MM-dd HH:mm:ss");
    var htmlStr = "<span class='text_red'>" + currentTimeStr + "</span> " + scwin.statusStr;
    document.getElementById('currentTimeDiv').innerHTML = htmlStr;
};
